    [6,6,6,6,6,5,6,6,6,6,6,6,6,6],
]
out += [[6]*14 for _ in range(9)]

bg = 6

# Check down shift: output row i matches input row i-1
def shift_down(inp):
    h, w = len(inp), len(inp[0])
    out = [[bg]*w for _ in range(h)]
    for i in range(1, h):
        for j in range(w):
            if inp[i-1][j] != bg:
                out[i][j] = inp[i-1][j]
    return out

result = shift_down(inp)
print("Output vs shifted input? ", result == out)
if result != out:
    print("\nFailed positions:")
    for i in range(len(result)):
        for j in range(len(result[0])):
            if result[i][j] != out[i][j]:
                print(f"  ({i},{j}): result={result[i][j]}, out={out[i][j]}")

print("\nVerifying each row:")
for i in range(max(len(inp), len(out))):
    inc = inp[i] if i < len(inp) else None
    otc = out[i]
    if inc:
        # Compare output[i] with input[i-1]
        prev = inp[i-1] if i > 0 else None
